"""OpenAlex API client."""

import logging

import httpx

from backend.pipeline.literature.base import AcademicSearchSource
from backend.pipeline.literature.models import Author, Paper, SearchResult

logger = logging.getLogger(__name__)

API_BASE = "https://api.openalex.org"


class OpenAlexSource(AcademicSearchSource):
    def __init__(self, email: str | None = None):
        params = {}
        if email:
            params["mailto"] = email
        self._client = httpx.AsyncClient(base_url=API_BASE, params=params, timeout=30.0)

    @property
    def source_name(self) -> str:
        return "openalex"

    async def search(
        self,
        query: str,
        limit: int = 20,
        year_from: int | None = None,
        year_to: int | None = None,
    ) -> list[SearchResult]:
        params = {"search": query, "per_page": min(limit, 50)}
        if year_from or year_to:
            year_filter = f"publication_year:{year_from or 2000}-{year_to or 2030}"
            params["filter"] = year_filter

        try:
            response = await self._client.get("/works", params=params)  # type: ignore[arg-type]
            response.raise_for_status()
            data = response.json()
        except httpx.HTTPError as e:
            logger.warning("OpenAlex search failed: %s", e)
            return []

        results = []
        for item in data.get("results", []):
            paper = self._parse_work(item)
            if paper:
                results.append(
                    SearchResult(
                        paper=paper,
                        relevance_score=item.get("relevance_score"),
                        source=self.source_name,
                    )
                )
        return results

    async def get_paper(self, paper_id: str) -> Paper | None:
        try:
            response = await self._client.get(f"/works/{paper_id}")
            response.raise_for_status()
            return self._parse_work(response.json())
        except httpx.HTTPError as e:
            logger.warning("OpenAlex get_paper failed: %s", e)
            return None

    async def get_citations(self, paper_id: str, limit: int = 50) -> list[Paper]:
        try:
            response = await self._client.get(
                "/works",
                params={"filter": f"cites:{paper_id}", "per_page": limit},
            )
            response.raise_for_status()
            return [
                p for item in response.json().get("results", []) if (p := self._parse_work(item))
            ]
        except httpx.HTTPError as e:
            logger.warning("OpenAlex citations failed: %s", e)
            return []

    async def get_references(self, paper_id: str, limit: int = 50) -> list[Paper]:
        try:
            response = await self._client.get(
                "/works",
                params={"filter": f"cited_by:{paper_id}", "per_page": limit},
            )
            response.raise_for_status()
            return [
                p for item in response.json().get("results", []) if (p := self._parse_work(item))
            ]
        except httpx.HTTPError as e:
            logger.warning("OpenAlex references failed: %s", e)
            return []

    def _parse_work(self, data: dict) -> Paper | None:
        if not data or not data.get("title"):
            return None

        authorships = data.get("authorships", []) or []
        doi_url = data.get("doi") or ""

        return Paper(
            id=data.get("id", "").split("/")[-1] if data.get("id") else "",
            source=self.source_name,
            title=data["title"],
            abstract=self._reconstruct_abstract(data.get("abstract_inverted_index")),
            authors=[
                Author(name=a.get("author", {}).get("display_name", "Unknown")) for a in authorships
            ],
            year=data.get("publication_year"),
            venue=((data.get("primary_location") or {}).get("source") or {}).get("display_name"),
            citation_count=data.get("cited_by_count"),
            url=data.get("id"),
            doi=doi_url.replace("https://doi.org/", "") if doi_url else None,
            keywords=[kw.get("display_name", "") for kw in (data.get("keywords") or []) if kw],
        )

    @staticmethod
    def _reconstruct_abstract(inverted_index: dict | None) -> str | None:
        if not inverted_index:
            return None
        word_positions: list[tuple[int, str]] = []
        for word, positions in inverted_index.items():
            for pos in positions:
                word_positions.append((pos, word))
        word_positions.sort()
        return " ".join(w for _, w in word_positions)

"""PDF parsing service — wraps S1-Parser or falls back to PyMuPDF."""

import logging
from pathlib import Path

from backend.pipeline.ingestion.chunker import DocumentChunk, chunk_text

logger = logging.getLogger(__name__)


class StructuredDocument:
    """Result of PDF parsing."""

    def __init__(self, text: str, pages: list[str] | None = None, metadata: dict | None = None):
        self.text = text
        self.pages = pages or []
        self.metadata = metadata or {}


class PDFService:
    """Parse PDFs into structured text using S1-Parser or PyMuPDF fallback."""

    def __init__(self, mode: str = "import", s1_parser_url: str = "http://localhost:8000"):
        self._mode = mode
        self._s1_url = s1_parser_url

    async def parse_pdf(self, file_path: str) -> StructuredDocument:
        """Parse a PDF file and return structured text."""
        path = Path(file_path)
        if not path.exists():
            raise FileNotFoundError(f"PDF not found: {file_path}")

        if self._mode == "import":
            return self._parse_via_import(file_path)
        else:
            return await self._parse_via_http(file_path)

    async def parse_and_chunk(
        self,
        file_path: str,
        paper_id: str,
        chunk_size: int = 1000,
        overlap: int = 200,
    ) -> list[DocumentChunk]:
        """Parse a PDF and split into chunks for embedding."""
        doc = await self.parse_pdf(file_path)
        return chunk_text(doc.text, paper_id, chunk_size=chunk_size, overlap=overlap)

    def _parse_via_import(self, file_path: str) -> StructuredDocument:
        """Use S1-Parser (magic_pdf) directly."""
        try:
            import fitz  # PyMuPDF as primary fallback

            doc = fitz.open(file_path)
            pages = [page.get_text() for page in doc]
            full_text = "\n\n".join(pages)
            doc.close()
            return StructuredDocument(
                text=full_text,
                pages=pages,
                metadata={"parser": "pymupdf", "page_count": len(pages)},
            )
        except ImportError:
            logger.warning("PyMuPDF not available, trying basic extraction")
            return self._basic_extraction(file_path)

    async def _parse_via_http(self, file_path: str) -> StructuredDocument:
        """Use S1-Parser via HTTP API."""
        import httpx

        async with httpx.AsyncClient(timeout=120.0) as client:
            with open(file_path, "rb") as f:
                response = await client.post(
                    f"{self._s1_url}/parse",
                    files={"file": f},
                )
            response.raise_for_status()
            data = response.json()
            return StructuredDocument(
                text=data.get("text", ""),
                pages=data.get("pages", []),
                metadata=data.get("metadata", {}),
            )

    @staticmethod
    def _basic_extraction(file_path: str) -> StructuredDocument:
        """Basic text extraction as last resort."""
        try:
            import pdfplumber

            pages = []
            with pdfplumber.open(file_path) as pdf:
                for page in pdf.pages:
                    text = page.extract_text() or ""
                    pages.append(text)
            return StructuredDocument(
                text="\n\n".join(pages),
                pages=pages,
                metadata={"parser": "pdfplumber", "page_count": len(pages)},
            )
        except ImportError:
            # Ultimate fallback: read raw bytes (will be garbage but won't crash)
            logger.error("No PDF parser available. Install PyMuPDF or pdfplumber.")
            return StructuredDocument(text="", metadata={"parser": "none"})

"""ObservabilityManager — creates processors, wires cost tracking, provides API."""

from __future__ import annotations

import logging
from typing import TYPE_CHECKING

from backend.pipeline.tracing.processor import (
    CompositeProcessor,
    InMemoryProcessor,
    LoggingProcessor,
    set_tracer,
)
from backend.pipeline.tracing.processor import TracingProcessor
from backend.pipeline.tracing.spans import Span

if TYPE_CHECKING:
    from backend.providers.provider_factory import CostTracker

logger = logging.getLogger(__name__)

_active: ObservabilityManager | None = None


def set_active_manager(mgr: ObservabilityManager | None) -> None:
    global _active
    _active = mgr


def get_active_manager() -> ObservabilityManager | None:
    return _active


class _CostLinkingProcessor(TracingProcessor):
    """Attaches cost data from CostTracker to completed spans."""

    def __init__(self, cost_tracker: CostTracker) -> None:
        self._tracker = cost_tracker

    def on_span_start(self, span: Span) -> None:
        pass

    def on_span_end(self, span: Span) -> None:
        if not span.start_time or not span.end_time:
            return
        events = self._tracker.events_in_range(span.start_time, span.end_time)
        if events:
            span.cost_usd = sum(e.cost_usd for e in events)
            span.token_count = sum(e.total_tokens for e in events)


class ObservabilityManager:
    """Owns and configures the tracing subsystem.

    Created by PipelineOrchestrator when observability_enabled=True.
    Builds a CompositeProcessor from config and installs it as global tracer.
    """

    def __init__(
        self,
        *,
        trace_logging: bool = True,
        trace_memory: bool = True,
        max_memory_spans: int = 10000,
        otlp_enabled: bool = False,
        otlp_endpoint: str = "http://localhost:4317",
        otlp_protocol: str = "grpc",
        metrics_enabled: bool = True,
        cost_tracker: CostTracker | None = None,
    ) -> None:
        self._composite = CompositeProcessor()
        self._memory_processor: InMemoryProcessor | None = None
        self._otlp_exporter = None
        self._metrics = None

        if trace_logging:
            self._composite.add(LoggingProcessor())

        if trace_memory:
            self._memory_processor = InMemoryProcessor(max_spans=max_memory_spans)
            self._composite.add(self._memory_processor)

        if metrics_enabled:
            from backend.pipeline.observability.metrics import MetricsCollector
            self._metrics = MetricsCollector()
            self._composite.add(self._metrics)

        if cost_tracker:
            self._composite.add(_CostLinkingProcessor(cost_tracker))

        if otlp_enabled:
            self._init_otlp(otlp_endpoint, otlp_protocol)

        set_tracer(self._composite)
        logger.info(
            "Observability initialized (processors: %d, otlp: %s, metrics: %s)",
            len(self._composite.processors),
            otlp_enabled,
            metrics_enabled,
        )

    def _init_otlp(self, endpoint: str, protocol: str) -> None:
        try:
            from backend.pipeline.observability.otlp_exporter import OTLPExporter
            self._otlp_exporter = OTLPExporter(endpoint=endpoint, protocol=protocol)
            self._composite.add(self._otlp_exporter)
        except ImportError:
            logger.warning(
                "OTLP exporter requested but opentelemetry packages not installed. "
                "Install with: pip install opentelemetry-api opentelemetry-sdk "
                "opentelemetry-exporter-otlp-proto-grpc"
            )

    def get_traces(self, trace_id: str) -> list[dict]:
        if not self._memory_processor:
            return []
        spans = self._memory_processor.query(trace_id)
        return [s.to_dict() for s in spans]

    def get_trace_summary(self) -> dict:
        if not self._memory_processor:
            return {"span_count": 0, "trace_count": 0}
        return self._memory_processor.summary()

    def get_metrics(self) -> dict:
        if not self._metrics:
            return {}
        return self._metrics.snapshot()

    def shutdown(self) -> None:
        if self._otlp_exporter and hasattr(self._otlp_exporter, "shutdown"):
            self._otlp_exporter.shutdown()

"""Provider registry with dynamic registration, override management, and cost tracking."""

from __future__ import annotations

import logging
from dataclasses import dataclass, field
from datetime import datetime, timezone
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from backend.providers.secrets import KeyVault

from backend.api.errors import ProviderConfigurationError
from backend.config import get_settings
from backend.providers.base import CostEvent, LLMProvider

logger = logging.getLogger(__name__)


class ProviderRegistry:
    """Mutable provider registry with override tracking and health checking.

    Inspired by Paperclip's mutable adapter registry with override pause/resume.
    Built-in providers are registered at init. External providers can be
    added, removed, or overridden at runtime without restart.
    """

    def __init__(self) -> None:
        self._providers: dict[str, type[LLMProvider]] = {}
        self._overrides: dict[str, type[LLMProvider]] = {}
        self._builtin_fallbacks: dict[str, type[LLMProvider]] = {}
        self._paused_overrides: set[str] = set()
        self._cost_tracker: CostTracker | None = None
        self._auto_register_builtins()

    def _auto_register_builtins(self) -> None:
        _BUILTIN_IMPORTS = [
            ("openai", "backend.providers.openai_provider", "OpenAIProvider"),
            ("anthropic", "backend.providers.anthropic_provider", "AnthropicProvider"),
            ("gemini", "backend.providers.gemini_provider", "GeminiProvider"),
            ("ollama", "backend.providers.ollama_provider", "OllamaProvider"),
            ("litellm", "backend.providers.litellm_provider", "LiteLLMProvider"),
            # LM Studio reuses AnthropicProvider (supports custom base_url)
            ("lmstudio", "backend.providers.anthropic_provider", "AnthropicProvider"),
        ]
        for name, module_path, cls_name in _BUILTIN_IMPORTS:
            try:
                import importlib
                mod = importlib.import_module(module_path)
                self._providers[name] = getattr(mod, cls_name)
            except ImportError:
                logger.debug("Skipping provider '%s': dependency not installed", name)

    def register(self, name: str, cls: type[LLMProvider]) -> None:
        self._providers[name] = cls
        logger.info("Registered provider: %s", name)

    def unregister(self, name: str) -> bool:
        if name in self._providers:
            del self._providers[name]
            self._overrides.pop(name, None)
            self._builtin_fallbacks.pop(name, None)
            self._paused_overrides.discard(name)
            logger.info("Unregistered provider: %s", name)
            return True
        return False

    def override(self, name: str, cls: type[LLMProvider]) -> None:
        """Override a provider with a custom implementation. Original is kept as fallback."""
        if name in self._providers:
            self._builtin_fallbacks[name] = self._providers[name]
        self._overrides[name] = cls
        self._providers[name] = cls
        logger.info("Overrode provider: %s", name)

    def set_override_paused(self, name: str, paused: bool) -> None:
        """Pause/resume an override, falling back to the builtin."""
        if paused and name in self._overrides and name in self._builtin_fallbacks:
            self._providers[name] = self._builtin_fallbacks[name]
            self._paused_overrides.add(name)
            logger.info("Paused override for provider: %s", name)
        elif not paused and name in self._paused_overrides and name in self._overrides:
            self._providers[name] = self._overrides[name]
            self._paused_overrides.discard(name)
            logger.info("Resumed override for provider: %s", name)

    def get(self, name: str) -> type[LLMProvider] | None:
        return self._providers.get(name)

    def list_providers(self) -> list[str]:
        return list(self._providers.keys())

    def set_cost_tracker(self, tracker: CostTracker) -> None:
        self._cost_tracker = tracker

    @property
    def cost_tracker(self) -> CostTracker | None:
        return self._cost_tracker

    def create(self, name: str | None = None, settings: Any = None) -> LLMProvider:
        """Create a configured provider instance.

        If name is None, uses settings.default_provider.
        If the provider name is unknown, falls back to LiteLLM when enabled.
        """
        settings = settings or get_settings()
        name = name or settings.default_provider

        self._validate_api_key(name, settings)

        if name not in self._providers:
            if getattr(settings, "litellm_fallback_enabled", False):
                from backend.providers.litellm_provider import LiteLLMProvider

                logger.info("Unknown provider '%s' — routing through LiteLLM", name)
                return LiteLLMProvider(model=name, api_key=settings.openai_api_key)
            raise ValueError(
                f"Unknown provider: {name}. Available: {self.list_providers()}"
            )

        cls = self._providers[name]
        provider = self._construct_provider(cls, name, settings)

        if self._cost_tracker:
            provider.set_cost_callback(self._cost_tracker.record)

        if getattr(settings, "caching_enabled", False):
            provider = _wrap_cached(provider, name, settings)

        if getattr(settings, "resilience_enabled", False):
            provider = _wrap_resilient(provider, name, settings)

        return provider

    def _construct_provider(
        self, cls: type[LLMProvider], name: str, settings: Any
    ) -> LLMProvider:
        """Generic provider constructor. Routes by name to pass the right settings."""
        if name == "openai":
            return cls(
                api_key=settings.openai_api_key,
                model=settings.openai_model,
                embedding_model=settings.embedding_model,
            )
        elif name == "anthropic":
            return cls(
                api_key=settings.anthropic_api_key,
                model=settings.anthropic_model,
                embedding_model=settings.embedding_model,
                base_url=settings.anthropic_base_url,
            )
        elif name == "gemini":
            return cls(
                api_key=settings.gemini_api_key,
                model=settings.gemini_model,
            )
        elif name == "ollama":
            return cls(
                base_url=settings.ollama_base_url,
                model=settings.ollama_model,
            )
        elif name == "litellm":
            return cls(
                model=settings.litellm_model,
                api_key=settings.openai_api_key,
            )
        elif name == "lmstudio":
            # LM Studio — Anthropic SDK pointed at local server
            return cls(
                api_key="lmstudio",
                model=settings.lmstudio_model,
                embedding_model=settings.embedding_model,
                base_url=settings.lmstudio_base_url,
            )
        else:
            return cls()

    @staticmethod
    def _validate_api_key(provider_name: str, settings: Any) -> None:
        _KEY_MAP = {
            "openai": ("openai_api_key", "EROCK_OPENAI_API_KEY"),
            "anthropic": ("anthropic_api_key", "EROCK_ANTHROPIC_API_KEY"),
            "gemini": ("gemini_api_key", "EROCK_GEMINI_API_KEY"),
            "litellm": ("openai_api_key", "EROCK_OPENAI_API_KEY"),
        }
        if provider_name not in _KEY_MAP:
            return
        attr_name, env_var = _KEY_MAP[provider_name]
        value = getattr(settings, attr_name, None)
        if not value or not value.strip():
            raise ProviderConfigurationError(
                detail=f"{env_var} not set",
                hint=(
                    f"Add it to .env or set the environment variable: "
                    f"export {env_var}=sk-... "
                    f"Or switch to a provider that doesn't require a key: ollama"
                ),
            )


# Module-level singleton
_registry: ProviderRegistry | None = None


def _get_registry() -> ProviderRegistry:
    global _registry
    if _registry is None:
        _registry = ProviderRegistry()
    return _registry


def get_registry() -> ProviderRegistry:
    """Get the global provider registry."""
    return _get_registry()


def register_provider(name: str, cls: type[LLMProvider]) -> None:
    """Register a custom provider. Backward-compatible entry point."""
    _get_registry().register(name, cls)


def create_provider(name: str | None = None) -> LLMProvider:
    """Create a configured provider. Drop-in replacement for the old factory."""
    return _get_registry().create(name)


def get_thinking_provider(settings: Any = None) -> LLMProvider:
    """Get the provider configured for thinking tasks (classification, extraction).

    If thinking_model is not configured, returns the default provider (HB-01).
    Falls back to generation provider on error (HB-02).
    """
    settings = settings or get_settings()
    model_name = getattr(settings, "thinking_model", "")
    if not model_name:
        return _get_registry().create(settings=settings)
    try:
        return _get_registry().create(name=model_name, settings=settings)
    except Exception as e:
        logger.warning("Thinking model '%s' unavailable, falling back to default: %s", model_name, e)
        return _get_registry().create(settings=settings)


def get_generation_provider(settings: Any = None) -> LLMProvider:
    """Get the provider configured for generation tasks (writing, synthesis).

    If generation_model is not configured, returns the default provider (HB-01).
    """
    settings = settings or get_settings()
    model_name = getattr(settings, "generation_model", "")
    if not model_name:
        return _get_registry().create(settings=settings)
    try:
        return _get_registry().create(name=model_name, settings=settings)
    except Exception as e:
        logger.warning("Generation model '%s' unavailable, falling back to default: %s", model_name, e)
        return _get_registry().create(settings=settings)


def _validate_api_key(provider_name: str, settings: Any) -> None:
    """Backward-compatible module-level alias."""
    ProviderRegistry._validate_api_key(provider_name, settings)


# ---- Resilience Wiring ----

_vault: KeyVault | None = None


def _get_vault(settings: Any) -> KeyVault | None:
    global _vault
    if _vault is not None:
        return _vault
    if not getattr(settings, "secrets_master_password", None):
        return None
    from backend.providers.secrets import KeyVault

    _vault = KeyVault(
        master_password=settings.secrets_master_password,
        persist_path=f"{settings.secrets_persist_dir}/vault.json",
    )
    try:
        _vault.load()
    except Exception:
        logger.warning("Failed to load key vault — starting fresh")
    return _vault


def _wrap_cached(
    provider: LLMProvider, name: str, settings: Any
) -> LLMProvider:
    from backend.providers.cache import CachedProvider, InMemoryCache, SemanticCache

    cache_type = getattr(settings, "caching_type", "memory")
    max_size = getattr(settings, "caching_max_size", 1000)
    ttl_seconds = getattr(settings, "caching_ttl_seconds", 3600)

    if cache_type == "semantic":
        from backend.pipeline.knowledge.embedding_providers import create_embedding_provider
        from backend.pipeline.knowledge.embedding_service import EmbeddingService

        emb_provider = create_embedding_provider(
            provider_name=getattr(settings, "embedding_provider", "openai"),
            model=getattr(settings, "embedding_model", "text-embedding-3-small"),
            api_key=getattr(settings, "openai_api_key", ""),
            base_url=getattr(settings, "ollama_base_url", "http://localhost:11434"),
            dimension=getattr(settings, "embedding_dimension", 1536) or None,
        )
        emb_service = EmbeddingService(
            emb_provider,
            batch_size=getattr(settings, "embedding_batch_size", 100),
        )
        semantic_cache = SemanticCache(
            embedding_service=emb_service,
            persist_dir=getattr(settings, "caching_persist_dir", "./data/chroma"),
            similarity_threshold=getattr(settings, "caching_similarity_threshold", 0.95),
            ttl_seconds=ttl_seconds,
            max_size=max_size,
        )
        memory_cache = InMemoryCache(max_size=max_size, ttl_seconds=ttl_seconds)
        return CachedProvider(
            wrapped=provider,
            cache=memory_cache,
            cache_type="semantic",
            semantic_cache=semantic_cache,
        )

    memory_cache = InMemoryCache(max_size=max_size, ttl_seconds=ttl_seconds)
    return CachedProvider(wrapped=provider, cache=memory_cache, cache_type="memory")


def _wrap_resilient(
    provider: LLMProvider, name: str, settings: Any
) -> LLMProvider:
    from backend.providers.resilience import CircuitBreaker, ResilientProvider, RetryConfig
    from backend.providers.resilience.circuit_breaker import _breakers

    breaker = _breakers.setdefault(
        name,
        CircuitBreaker(
            failure_threshold=settings.circuit_breaker_failure_threshold,
            reset_timeout=settings.circuit_breaker_reset_timeout,
            cooldown_percent=getattr(settings, "circuit_breaker_cooldown_percent", 0.1),
        ),
    )
    retry_config = RetryConfig(
        max_retries=settings.retry_max_retries,
        base_delay=settings.retry_base_delay,
        max_delay=settings.retry_max_delay,
        cooldown_delay=settings.retry_cooldown_delay,
    )
    vault = _get_vault(settings)
    return ResilientProvider(provider, breaker, retry_config, vault)


# ---- Cost Tracking ----

class CostTracker:
    """Per-provider cost tracking with multi-dimensional aggregation.

    Inspired by Paperclip's cost tracking with 6 aggregation dimensions.
    """

    # Rough per-1K-token costs (USD). Can be overridden per provider/model.
    DEFAULT_COSTS: dict[str, dict[str, float]] = {
        "openai": {"input": 0.0025, "output": 0.01},
        "anthropic": {"input": 0.003, "output": 0.015},
        "gemini": {"input": 0.00125, "output": 0.005},
        "ollama": {"input": 0.0, "output": 0.0},
        "litellm": {"input": 0.0025, "output": 0.01},
    }

    def __init__(self) -> None:
        self._events: list[CostEvent] = []
        self._cost_overrides: dict[str, dict[str, float]] = {}

    def set_cost_per_1k(self, provider: str, input_cost: float, output_cost: float) -> None:
        self._cost_overrides[provider] = {"input": input_cost, "output": output_cost}

    def record(self, event: CostEvent) -> None:
        if event.cost_usd == 0.0:
            rates = self._cost_overrides.get(event.provider, self.DEFAULT_COSTS.get(event.provider, {"input": 0.0, "output": 0.0}))
            event.cost_usd = (
                (event.input_tokens / 1000.0) * rates.get("input", 0.0)
                + (event.output_tokens / 1000.0) * rates.get("output", 0.0)
            )
        self._events.append(event)

    def summary(self) -> dict[str, Any]:
        if not self._events:
            return {"total_cost_usd": 0.0, "total_tokens": 0, "event_count": 0}
        return {
            "total_cost_usd": sum(e.cost_usd for e in self._events),
            "total_tokens": sum(e.total_tokens for e in self._events),
            "total_input_tokens": sum(e.input_tokens for e in self._events),
            "total_output_tokens": sum(e.output_tokens for e in self._events),
            "event_count": len(self._events),
        }

    def by_provider(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            if e.provider not in result:
                result[e.provider] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[e.provider]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_stage(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            stage = e.stage or "unspecified"
            if stage not in result:
                result[stage] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[stage]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def by_model(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for e in self._events:
            key = f"{e.provider}/{e.model}"
            if key not in result:
                result[key] = {"cost_usd": 0.0, "input_tokens": 0, "output_tokens": 0, "calls": 0}
            r = result[key]
            r["cost_usd"] += e.cost_usd
            r["input_tokens"] += e.input_tokens
            r["output_tokens"] += e.output_tokens
            r["calls"] += 1
        return result

    def reset(self) -> None:
        self._events.clear()

    def events_in_range(self, start: float, end: float) -> list:
        """Return cost events whose timestamp falls within [start, end] epoch seconds."""
        return [
            e for e in self._events
            if start <= e.timestamp.timestamp() <= end
        ]

    def persist(self, path: str) -> None:
        """Write all cost events to a JSONL file."""
        from pathlib import Path
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            for e in self._events:
                line = json.dumps({
                    "provider": e.provider,
                    "model": e.model,
                    "input_tokens": e.input_tokens,
                    "output_tokens": e.output_tokens,
                    "cost_usd": e.cost_usd,
                    "stage": e.stage,
                    "run_id": e.run_id,
                    "timestamp": e.timestamp.isoformat(),
                })
                f.write(line + "\n")

    @classmethod
    def load(cls, path: str) -> "CostTracker":
        """Load cost events from a JSONL file."""
        tracker = cls()
        from backend.providers.base import CostEvent
        from datetime import datetime, timezone
        with open(path, encoding="utf-8") as f:
            for line in f:
                data = json.loads(line.strip())
                event = CostEvent(
                    provider=data["provider"],
                    model=data["model"],
                    input_tokens=data["input_tokens"],
                    output_tokens=data["output_tokens"],
                    cost_usd=data.get("cost_usd", 0.0),
                    stage=data.get("stage", ""),
                    run_id=data.get("run_id"),
                    timestamp=datetime.fromisoformat(data.get("timestamp", datetime.now(timezone.utc).isoformat())),
                )
                tracker._events.append(event)
        return tracker

"""Embedding provider abstraction — pluggable embedding backends.

Separates embedding generation from LLM completion, allowing different
models and providers for each task.

Reference: mem0 EmbedderFactory (11 providers), letta EmbeddingConfig (16 endpoint types).
"""

from __future__ import annotations

import asyncio
import hashlib
import logging
from abc import ABC, abstractmethod

logger = logging.getLogger(__name__)


class EmbeddingProvider(ABC):
    """Abstract embedding provider."""

    @abstractmethod
    async def embed(self, texts: list[str]) -> list[list[float]]:
        """Generate embeddings for a list of texts."""
        ...

    @property
    @abstractmethod
    def dimension(self) -> int:
        """Return the embedding dimension for this provider."""
        ...

    @property
    @abstractmethod
    def provider_name(self) -> str:
        """Return the provider name for logging."""
        ...


class OpenAIEmbeddingProvider(EmbeddingProvider):
    """OpenAI embeddings via the openai SDK."""

    def __init__(
        self,
        model: str = "text-embedding-3-small",
        api_key: str | None = None,
        dimension_override: int | None = None,
    ):
        import openai

        self._client = openai.AsyncOpenAI(api_key=api_key) if api_key else openai.AsyncOpenAI()
        self._model = model
        self._dimension = dimension_override or self._default_dimension(model)

    @staticmethod
    def _default_dimension(model: str) -> int:
        dims = {
            "text-embedding-3-small": 1536,
            "text-embedding-3-large": 3072,
            "text-embedding-ada-002": 1536,
        }
        return dims.get(model, 1536)

    async def embed(self, texts: list[str]) -> list[list[float]]:
        response = await self._client.embeddings.create(model=self._model, input=texts)
        return [item.embedding for item in response.data]

    @property
    def dimension(self) -> int:
        return self._dimension

    @property
    def provider_name(self) -> str:
        return f"openai:{self._model}"


class GeminiEmbeddingProvider(EmbeddingProvider):
    """Google Gemini embeddings via the generativeai SDK."""

    def __init__(
        self,
        model: str = "models/embedding-001",
        api_key: str | None = None,
    ):
        import google.generativeai as genai

        if api_key:
            genai.configure(api_key=api_key)
        self._model = model
        self._genai = genai

    async def embed(self, texts: list[str]) -> list[list[float]]:
        result = await asyncio.to_thread(
            self._genai.embed_content,
            model=self._model,
            content=texts,
            task_type="retrieval_document",
        )
        return result["embedding"]

    @property
    def dimension(self) -> int:
        dims = {
            "models/embedding-001": 768,
            "models/text-embedding-004": 768,
        }
        return dims.get(self._model, 768)

    @property
    def provider_name(self) -> str:
        return f"gemini:{self._model}"


class OllamaEmbeddingProvider(EmbeddingProvider):
    """Ollama embeddings via local HTTP API."""

    def __init__(
        self,
        model: str = "nomic-embed-text",
        base_url: str = "http://localhost:11434",
    ):
        import httpx

        self._client = httpx.AsyncClient(timeout=60.0)
        self._model = model
        self._base_url = base_url
        self._dim: int | None = None

    async def embed(self, texts: list[str]) -> list[list[float]]:
        embeddings = []
        for text in texts:
            response = await self._client.post(
                f"{self._base_url}/api/embeddings",
                json={"model": self._model, "prompt": text},
            )
            response.raise_for_status()
            emb = response.json()["embedding"]
            embeddings.append(emb)
            if self._dim is None:
                self._dim = len(emb)
        return embeddings

    @property
    def dimension(self) -> int:
        return self._dim or 768

    @property
    def provider_name(self) -> str:
        return f"ollama:{self._model}"


class FallbackEmbeddingProvider(EmbeddingProvider):
    """Provider that tries primary, then falls back to secondary on failure."""

    def __init__(self, primary: EmbeddingProvider, fallback: EmbeddingProvider):
        self._primary = primary
        self._fallback = fallback

    async def embed(self, texts: list[str]) -> list[list[float]]:
        try:
            return await self._primary.embed(texts)
        except Exception as e:
            logger.warning(
                "Primary embedding provider %s failed: %s, using fallback",
                self._primary.provider_name,
                e,
            )
            return await self._fallback.embed(texts)

    @property
    def dimension(self) -> int:
        return self._primary.dimension

    @property
    def provider_name(self) -> str:
        return f"fallback({self._primary.provider_name}+{self._fallback.provider_name})"


class DummyEmbeddingProvider(EmbeddingProvider):
    """No-op embedding provider for testing / environments without API access.

    Returns deterministic zero vectors of the configured dimension.
    Useful when the LLM provider (e.g. z.ai) does not offer an embedding endpoint.
    """

    def __init__(self, dimension: int = 1536):
        self._dimension = dimension

    async def embed(self, texts: list[str]) -> list[list[float]]:
        return [[0.0] * self._dimension for _ in texts]

    @property
    def dimension(self) -> int:
        return self._dimension

    @property
    def provider_name(self) -> str:
        return f"dummy:{self._dimension}d"


class CachedEmbeddingProvider(EmbeddingProvider):
    """Caching wrapper — stores text_hash → embedding in memory.

    Avoids re-embedding identical text across pipeline stages.
    """

    def __init__(self, wrapped: EmbeddingProvider, max_size: int = 10000):
        self._wrapped = wrapped
        self._cache: dict[str, list[float]] = {}
        self._max_size = max_size
        self._hits = 0
        self._misses = 0

    async def embed(self, texts: list[str]) -> list[list[float]]:
        results: list[list[float] | None] = [None] * len(texts)
        uncached_indices: list[int] = []
        uncached_texts: list[str] = []

        for i, text in enumerate(texts):
            key = hashlib.sha256(text.encode()).hexdigest()
            if key in self._cache:
                results[i] = self._cache[key]
                self._hits += 1
            else:
                uncached_indices.append(i)
                uncached_texts.append(text)
                self._misses += 1

        if uncached_texts:
            embeddings = await self._wrapped.embed(uncached_texts)
            for idx, emb in zip(uncached_indices, embeddings):
                results[idx] = emb
                key = hashlib.sha256(texts[idx].encode()).hexdigest()
                if len(self._cache) < self._max_size:
                    self._cache[key] = emb

        total = self._hits + self._misses
        if total > 0 and total % 100 == 0:
            logger.info(
                "Embedding cache: %d hits / %d total (%.1f%%)",
                self._hits, total, 100 * self._hits / total,
            )

        return results  # type: ignore[return-value]

    @property
    def dimension(self) -> int:
        return self._wrapped.dimension

    @property
    def provider_name(self) -> str:
        return f"cached({self._wrapped.provider_name})"


def create_embedding_provider(
    provider_name: str,
    model: str | None = None,
    api_key: str | None = None,
    base_url: str | None = None,
    dimension: int | None = None,
) -> EmbeddingProvider:
    """Factory: create an EmbeddingProvider by name.

    Args:
        provider_name: "openai", "gemini", "ollama"
        model: Model name (provider-specific default if omitted)
        api_key: API key for cloud providers
        base_url: Base URL for Ollama
        dimension: Override embedding dimension
    """
    name = provider_name.lower().strip()

    if name in ("dummy", "noop", "test"):
        return DummyEmbeddingProvider(dimension=dimension or 1536)
    elif name == "openai":
        provider = OpenAIEmbeddingProvider(
            model=model or "text-embedding-3-small",
            api_key=api_key,
            dimension_override=dimension,
        )
    elif name in ("gemini", "google"):
        provider = GeminiEmbeddingProvider(
            model=model or "models/embedding-001",
            api_key=api_key,
        )
    elif name == "ollama":
        return OllamaEmbeddingProvider(
            model=model or "nomic-embed-text",
            base_url=base_url or "http://localhost:11434",
        )
    else:
        raise ValueError(f"Unknown embedding provider: {provider_name}")

    # Wrap cloud providers with cache (local Ollama doesn't benefit)
    return CachedEmbeddingProvider(provider)

